-- Every fixture, customer role and synthetic order is rolled back. No external messages.
begin;
do $qa$
declare attempt uuid:=gen_random_uuid(); secret uuid:=gen_random_uuid(); token uuid; product jsonb; payload jsonb; row jsonb; result jsonb; denied boolean;
 actor uuid; prior_user uuid; original jsonb; snapshot jsonb; hash text:=repeat('b',64); current_revision bigint;
begin
 select data into original from public.app_state where id=1;
 select value into product from jsonb_array_elements(original->'products') where value->>'active'='true' limit 1;
 payload:=jsonb_build_object('phone','21900000001','firstName','Marina','lastName','Teste','email','marina@example.invalid','consent',true,'delivery','Entrega','locality','Nova Iguaçu / RJ','phase','contact',
  'cpf','NEVER STORE','address','NEVER STORE','password','NEVER STORE','items',jsonb_build_array(jsonb_build_object('id',product->'id','qty',1,'price',0,'cost',10,'options','{}'::jsonb)));
 assert not has_function_privilege('anon','public.capture_checkout_recovery(uuid,uuid,jsonb,bigint,text)','execute'),'Anonymous users cannot bypass the ingestion server';
 assert not has_function_privilege('authenticated','public.capture_checkout_recovery(uuid,uuid,jsonb,bigint,text)','execute'),'Signed-in customers cannot bypass ingestion';
 assert has_function_privilege('service_role','public.capture_checkout_recovery(uuid,uuid,jsonb,bigint,text)','execute'),'The ingestion server can write';
 assert not has_function_privilege('anon','public.list_checkout_recovery(text,text,integer,integer)','execute'),'Anonymous users cannot list contacts';
 assert not has_table_privilege('authenticated','private.checkout_recovery','select'),'No direct private-table reads';
 assert public.capture_checkout_recovery(attempt,secret,payload,1,hash),'Valid identified checkout is captured';
 select recovery_token,revision into token,current_revision from private.checkout_recovery where id=attempt;
 assert (select subtotal>0 and items->0->>'price'<>'0' from private.checkout_recovery where id=attempt),'The server derives prices';
 assert (select subtotal from private.checkout_recovery where id=attempt)=case when coalesce((product->>'promoPrice')::numeric,0)>0 and (product->>'promoPrice')::numeric<(product->>'price')::numeric then (product->>'promoPrice')::numeric else (product->>'price')::numeric end,'The draft uses the same valid promotional price as the storefront';
 assert (select to_jsonb(r)::text not like '%NEVER STORE%' and items->0->>'cost' is null from private.checkout_recovery r where id=attempt),'Only allowed data is stored';
 assert not public.capture_checkout_recovery(attempt,gen_random_uuid(),payload,2,hash),'Another session cannot modify a checkout';
 perform public.capture_checkout_recovery(attempt,secret,payload||'{"consent":false}',2,hash);
 assert (select not consent from private.checkout_recovery where id=attempt),'Consent withdrawal is immediate, including within the throttle';
 update private.checkout_recovery set last_seen=clock_timestamp()-interval '31 minutes' where id=attempt;
 perform public.capture_checkout_recovery(attempt,secret,payload,3,hash);
 update private.checkout_recovery set last_seen=clock_timestamp()-interval '31 minutes' where id=attempt;
 assert public.resume_checkout_recovery(token)->'items'->0->'id'=product->'id','Recovery links restore public cart content';
 assert not (public.resume_checkout_recovery(token) ?| array['phone','email','first_name','secret_hash','address']),'Recovery links never disclose personal data';
 assert public.resume_checkout_recovery(gen_random_uuid()) is null,'Unknown recovery links reveal nothing';
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 denied:=false;begin perform public.list_checkout_recovery();exception when insufficient_privilege then denied:=true;end;assert denied,'Unknown identities cannot read contacts';
 select user_id into actor from public.profiles where role='customer' limit 1;assert actor is not null,'An existing fixture actor is required';
 update public.profiles set role='admin',position='Vendedor' where user_id=actor;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 result:=public.list_checkout_recovery('marina@example.invalid','pending',30,1);
 assert jsonb_array_length(result->'rows')=1,'A seller can see an abandoned, authorized checkout';
 row:=public.checkout_recovery_detail(attempt);
 assert row->>'stage'='pending' and not(row ?| array['secret_hash','client_hash','sequence']),'Staff response is sanitized';
 row:=public.update_checkout_recovery(attempt,'opened',(row->>'revision')::bigint);
 assert (row->>'contact_count')::integer=0 and row->>'status'='open','Opening WhatsApp is not a contact or sale';
 denied:=false;begin perform public.update_checkout_recovery(attempt,'contacted',1);exception when serialization_failure then denied:=true;end;assert denied,'Stale changes are rejected';
 row:=public.update_checkout_recovery(attempt,'contacted',(row->>'revision')::bigint);
 assert (row->>'contact_count')::integer=1 and row->>'stage'='contacted','Attested contacts have their own state';
 denied:=false;begin perform public.update_checkout_recovery(attempt,'contacted',(row->>'revision')::bigint);exception when others then denied:=true;end;assert denied,'Repeated contacts are paced';
 row:=public.update_checkout_recovery(attempt,'waiting',(row->>'revision')::bigint);
 row:=public.update_checkout_recovery(attempt,'note',(row->>'revision')::bigint,'Cliente quer confirmar as medidas.');assert row->>'notes'<>'';
 -- Creating an actual order on another device atomically suppresses reminders by exact phone.
 snapshot:=original||jsonb_build_object('orders',(original->'orders')||jsonb_build_array(jsonb_build_object('id',900000001,'customer','QA recovery','phone','21900000001','email','marina@example.invalid','status','pending','paid',false,'createdAt',clock_timestamp(),'items','[]'::jsonb,'freight',0)));
 update public.app_state set data=snapshot,version=version+1 where id=1;
 row:=public.checkout_recovery_detail(attempt);
 assert row->>'stage'='converted' and row->>'order_id'='900000001','Pending-payment orders are no longer abandoned checkouts';
 assert public.resume_checkout_recovery(token) is null,'Completed checkout links cannot reopen the old reminder';
 denied:=false;begin perform public.update_checkout_recovery(attempt,'opened',(row->>'revision')::bigint);exception when others then denied:=true;end;assert denied,'A post-purchase WhatsApp action is rejected';
 assert public.capture_checkout_recovery(gen_random_uuid(),gen_random_uuid(),payload,1,hash),'A late first capture is safely acknowledged';
 assert (select count(*) from private.checkout_recovery where phone='+5521900000001')=1,'Late capture cannot recreate a reminder after ordering';
 row:=public.update_checkout_recovery(attempt,'optout',(row->>'revision')::bigint);assert not(row->>'consent')::boolean;
 assert exists(select 1 from private.checkout_contact_blocks where phone_hash=encode(sha256(convert_to('+5521900000001','UTF8')),'hex')),'Refusals suppress later contact';
 update public.profiles set role='driver',position='Entregador' where user_id=actor;
 denied:=false;begin perform public.checkout_recovery_detail(attempt);exception when insufficient_privilege then denied:=true;end;assert denied,'Drivers cannot read recovery contacts';
 update public.profiles set role='customer',position=null where user_id=actor;
 denied:=false;begin perform public.list_checkout_recovery();exception when insufficient_privilege then denied:=true;end;assert denied,'Customers cannot read recovery contacts';
 update public.profiles set role='admin',position='Gerente' where user_id=actor;
 assert public.list_checkout_recovery('marina@example.invalid','converted')->>'total'='1','Managers can see the recovery queue';
 perform set_config('request.jwt.claim.sub',(select user_id::text from private.master_account where singleton=1),true);
 assert public.list_checkout_recovery('marina@example.invalid','converted')->>'total'='1','Master can see order conversion';
 update private.checkout_recovery set created_at=clock_timestamp()-interval '31 days' where id=attempt;
 perform private.purge_checkout_recovery();assert not exists(select 1 from private.checkout_recovery where id=attempt),'Retention removes old contact data';
end $qa$;
rollback;
